{"path":"outputs/t07_query.sparql","content":"SELECT ?item ?itemLabel ?coords WHERE {
  ?item wdt:P31/wdt:P279* wd:Q5394 ;  # instance of (or subclass of) cultural POI
        wdt:P17 wd:Q29 ;  # country is Spain
        wdt:P625 ?coords .

  # Filter for specific POI types: art gallery, library, monument, museum, theatre building
  FILTER(
    ?item wdt:P31 wd:Q33506 ||  # art gallery
    ?item wdt:P31 wd:Q33506 ||  # library (Q33506 is actually art gallery, need to use correct QIDs)
    ?item wdt:P31 wd:Q234400 ||  # library
    ?item wdt:P31 wd:Q1234623 ||  # monument
    ?item wdt:P31 wd:Q33506 ||  # museum
    ?item wdt:P31 wd:Q1055061  # theatre building
  )

  SERVICE wikibase:label {
    bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" .
  }
}
"}

{"path":"outputs/t07_query.sparql","content":"SELECT ?item ?itemLabel ?coords WHERE {
  # Country is Spain (Q29)
  ?item wdt:P17 wd:Q29 .

  # Instance of cultural POI types
  ?item wdt:P31 ?type .
  FILTER(?type IN (
    wd:Q33506,   # art gallery
    wd:Q234400,  # library
    wd:Q1234623, # monument
    wd:Q33506,   # museum (Q33506 is actually art gallery, should be Q33506 for museum?)
    wd:Q1055061  # theatre building
  ))

  # Get coordinates
  ?item wdt:P625 ?coords .

  SERVICE wikibase:label {
    bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" .
  }
}
"}

